import React, { useEffect, useState, useRef } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';

export default function {{component_name}}() {
  const [phase, setPhase] = useState('work');
  const [left, setLeft] = useState({{work_seconds}});
  const [running, setRunning] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    if (!running) return;
    ref.current = setInterval(() => {
      setLeft(s => {
        if (s > 1) return s - 1;
        setPhase(p => (p === 'work' ? 'rest' : 'work'));
        return phase === 'work' ? {{rest_seconds}} : {{work_seconds}};
      });
    }, 1000);
    return () => clearInterval(ref.current);
  }, [running, phase]);

  return (
    <View style={styles.box}>
      <Text style={styles.phase}>{phase.toUpperCase()}</Text>
      <Text style={styles.time}>{left}s</Text>
      <TouchableOpacity style={styles.btn} onPress={() => setRunning(r => !r)}>
        <Text style={styles.btnTxt}>{running ? 'Pause' : 'Start'}</Text>
      </TouchableOpacity>
    </View>
  );
}
const styles = StyleSheet.create({
  box: { alignItems: 'center', padding: 32 },
  phase: { fontSize: 18, color: '#666' },
  time: { fontSize: 72, fontWeight: '800', marginVertical: 12 },
  btn: { backgroundColor: '#111', paddingHorizontal: 32, paddingVertical: 12, borderRadius: 24 },
  btnTxt: { color: '#fff', fontSize: 16 }
});
